class Instr(CuteMixin, metaclass=MetaCute):
  """
  The cute side of Qt's QV4::Moth::Instr: a plain Python object standing in
  front of one C++ QV4::Moth::Instr.

  C++ hands a QV4::Moth::Instr around as a copy, so every C++
  QV4::Moth::Instr behind a cute one is Python's own: it is removed, by the
  ritual named in '__delete_ritual__', when the cute object goes.

  What exists
  -----------

  Every function of Qt's QV4::Moth::Instr that has a ritual and that Python
  can call so far, 5 names in all: 'wideInstructionType',
  'narrowInstructionType', 'isWide', 'isNarrow', 'encodedLength'. None can be
  made from Python: one comes out of a function of another class that gives
  one back.

  What has a ritual and is left out, and why
  ------------------------------------------

  - Qt's 'Type QV4::Moth::Instr::unpack(const uchar *c)': names 'uchar',
    which has no cute class yet.
  - Qt's 'QV4::Moth::Instr::~Instr()': the destructor: Python removes its C++
    QV4::Moth::Instr by it, and has no other use for it.

  What has no ritual
  ------------------

  1 of the 8 functions Qt declares: 1 takes or gives a type that cannot be
  passed yet.

  What to expect
  --------------

  - The C++ QV4::Moth::Instr is created at the first use, not by
    'QV4::Moth::Instr(...)'.
  - A wrong argument is refused in Python, with 'DispatchException', and
    never reaches C++.
  - None is taken wherever Qt takes an object by its address, or text as C
    has it, and is passed on as nothing. Whether Qt can do with nothing there
    is as in C++.
  - A function giving a QV4::Moth::Instr back gives a copy the ritual made
    for Python, in a new cute QV4::Moth::Instr.
  - Each name of Qt's QV4::Moth::Instr that has no cute function yet, 'pack',
    'unpack', holds a function that raises 'NotImplementedError', and its
    docstring says why.
  """

